[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>GlobalStone — Global Commercial Real Estate Services</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --green:#003F2D;--teal:#012A2D;--teal-light:#0A4A4E;--gold:#C9A84C;
  --navy:#0A1628;--gray-50:#F9FAFB;--gray-100:#F3F4F6;--gray-200:#E5E7EB;
  --gray-300:#D1D5DB;--gray-400:#9CA3AF;--gray-500:#6B7280;--gray-600:#4B5563;
  --gray-700:#374151;--gray-800:#1F2937;--gray-900:#111827;--white:#FFFFFF;
  --font-sans:'Inter',system-ui,-apple-system,sans-serif;
  --font-serif:'Playfair Display',Georgia,serif;
}
html{scroll-behavior:smooth}
body{font-family:var(--font-sans);color:var(--gray-800);background:var(--white);line-height:1.6;-webkit-font-smoothing:antialiased}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}
.container{max-width:1280px;margin:0 auto;padding:0 24px}
@media(min-width:768px){.container{padding:0 40px}}
@media(min-width:1024px){.container{padding:0 64px}}

/* ===== HEADER & NAV ===== */
.header{position:fixed;top:0;left:0;right:0;z-index:1000;background:var(--white);border-bottom:1px solid var(--gray-200);transition:box-shadow .3s}
.header.scrolled{box-shadow:0 2px 20px rgba(0,0,0,.08)}
.header-inner{display:flex;align-items:center;justify-content:space-between;height:72px}
.logo{font-family:var(--font-serif);font-size:1.5rem;font-weight:700;color:var(--green);letter-spacing:-.5px}
.logo span{color:var(--gold)}
.nav-desktop{display:none;align-items:center;gap:32px}
@media(min-width:1024px){.nav-desktop{display:flex}}
.nav-link{font-size:.875rem;font-weight:500;color:var(--gray-700);transition:color .2s;position:relative;padding:4px 0}
.nav-link:hover{color:var(--green)}
.nav-link.has-dropdown{cursor:pointer;display:flex;align-items:center;gap:4px}
.nav-link.has-dropdown::after{content:'';border:solid var(--gray-500);border-width:0 1.5px 1.5px 0;display:inline-block;padding:2.5px;transform:rotate(45deg);margin-top:-3px;transition:transform .2s}
.nav-link.has-dropdown.open::after{transform:rotate(-135deg);margin-top:2px}
.nav-cta{background:var(--green);color:var(--white);padding:8px 20px;border-radius:4px;font-size:.8125rem;font-weight:600;transition:background .2s}
.nav-cta:hover{background:var(--teal)}

/* Mega Menu */
.mega-menu{position:absolute;top:72px;left:0;right:0;background:var(--white);border-top:1px solid var(--gray-200);box-shadow:0 20px 60px rgba(0,0,0,.1);opacity:0;visibility:hidden;transform:translateY(-8px);transition:all .25s ease;z-index:999}
.mega-menu.open{opacity:1;visibility:visible;transform:translateY(0)}
.mega-menu-inner{display:grid;grid-template-columns:1fr 1fr;gap:48px;padding:40px 0}
.mega-col-title{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;color:var(--gray-400);margin-bottom:20px}
.mega-menu a{display:block;padding:8px 0;font-size:.9375rem;color:var(--gray-700);transition:color .15s,padding-left .15s}
.mega-menu a:hover{color:var(--green);padding-left:4px}

/* Mobile Nav */
.hamburger{display:flex;flex-direction:column;gap:5px;cursor:pointer;padding:8px}
@media(min-width:1024px){.hamburger{display:none}}
.hamburger span{width:24px;height:2px;background:var(--gray-700);transition:all .3s}
.hamburger.open span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.hamburger.open span:nth-child(2){opacity:0}
.hamburger.open span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}
.mobile-nav{position:fixed;top:72px;left:0;right:0;bottom:0;background:var(--white);z-index:998;overflow-y:auto;transform:translateX(100%);transition:transform .3s ease}
.mobile-nav.open{transform:translateX(0)}
.mobile-nav-item{border-bottom:1px solid var(--gray-200)}
.mobile-nav-link{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;font-size:1rem;font-weight:500;color:var(--gray-800)}
.mobile-nav-link .arrow{transition:transform .2s;font-size:.75rem}
.mobile-nav-link.open .arrow{transform:rotate(180deg)}
.mobile-subnav{max-height:0;overflow:hidden;transition:max-height .3s ease;background:var(--gray-50)}
.mobile-subnav.open{max-height:600px}
.mobile-subnav a{display:block;padding:12px 24px 12px 40px;font-size:.9375rem;color:var(--gray-600)}
.mobile-subnav a:hover{color:var(--green)}

/* ===== HERO ===== */
.hero{position:relative;min-height:600px;display:flex;align-items:center;margin-top:72px;overflow:hidden;background:linear-gradient(135deg,var(--navy) 0%,var(--teal) 50%,var(--green) 100%)}
.hero-overlay{position:absolute;inset:0;background:url('https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1600&q=80') center/cover;opacity:.2}
.hero-content{position:relative;z-index:2;max-width:720px;padding:80px 0}
.hero-eyebrow{font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:2px;color:var(--gold);margin-bottom:16px}
.hero-title{font-family:var(--font-serif);font-size:2.75rem;font-weight:600;color:var(--white);line-height:1.15;margin-bottom:20px}
@media(min-width:768px){.hero-title{font-size:3.5rem}}
.hero-subtitle{font-size:1.125rem;color:rgba(255,255,255,.8);line-height:1.7;margin-bottom:32px;max-width:560px}
.btn-primary{display:inline-flex;align-items:center;gap:8px;background:var(--gold);color:var(--navy);padding:14px 32px;border-radius:4px;font-size:.9375rem;font-weight:600;border:none;cursor:pointer;transition:all .2s}
.btn-primary:hover{background:#d4b35e;transform:translateY(-1px)}
.btn-outline{display:inline-flex;align-items:center;gap:8px;background:transparent;color:var(--green);padding:12px 28px;border-radius:4px;font-size:.9375rem;font-weight:600;border:2px solid var(--green);cursor:pointer;transition:all .2s}
.btn-outline:hover{background:var(--green);color:var(--white)}
.btn-text{display:inline-flex;align-items:center;gap:6px;font-size:.9375rem;font-weight:600;color:var(--green);cursor:pointer;transition:gap .2s}
.btn-text:hover{gap:10px}
.btn-text-light{color:var(--white)}
.btn-text-light::after{content:'→'}
.btn-text::after{content:'→'}

/* ===== FEATURED INSIGHTS ===== */
.featured-insights{padding:64px 0;background:var(--white)}
.section-label{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:2px;color:var(--green);margin-bottom:8px}
.section-title{font-family:var(--font-serif);font-size:2rem;font-weight:600;color:var(--gray-900);margin-bottom:40px}
@media(min-width:768px){.section-title{font-size:2.5rem}}
.insights-grid{display:grid;grid-template-columns:1fr;gap:24px}
@media(min-width:768px){.insights-grid{grid-template-columns:repeat(3,1fr)}}
.insight-card{background:var(--gray-50);border-radius:8px;overflow:hidden;transition:transform .3s,box-shadow .3s}
.insight-card:hover{transform:translateY(-4px);box-shadow:0 12px 40px rgba(0,0,0,.08)}
.insight-img{height:200px;background:linear-gradient(135deg,var(--teal),var(--green));position:relative;overflow:hidden}
.insight-img-inner{position:absolute;inset:0;background:url('https://images.unsplash.com/photo-1497366216548-37526070297c?w=600&q=80') center/cover;opacity:.6}
.insight-tag{position:absolute;top:16px;left:16px;background:var(--gold);color:var(--navy);padding:4px 12px;border-radius:2px;font-size:.6875rem;font-weight:700;text-transform:uppercase;letter-spacing:.5px}
.insight-body{padding:24px}
.insight-cat{font-size:.75rem;font-weight:600;color:var(--green);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px}
.insight-title{font-family:var(--font-serif);font-size:1.125rem;font-weight:600;color:var(--gray-900);line-height:1.4;margin-bottom:12px}
.insight-title:hover{color:var(--green)}
.insight-desc{font-size:.875rem;color:var(--gray-500);line-height:1.6}

/* ===== ANNOUNCEMENT BANNER ===== */
.announcement{background:var(--green);padding:24px 0}
.announcement-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.announcement-text{font-size:1rem;font-weight:500;color:var(--white)}
.announcement .btn-primary{background:var(--gold);color:var(--navy);padding:10px 24px;font-size:.8125rem}

/* ===== ABOUT STATEMENT ===== */
.about{padding:80px 0;background:var(--white)}
.about-inner{display:grid;grid-template-columns:1fr;gap:48px;align-items:center}
@media(min-width:768px){.about-inner{grid-template-columns:1fr 1fr}}
.about-text{font-family:var(--font-serif);font-size:1.5rem;color:var(--gray-800);line-height:1.6;font-weight:500}
@media(min-width:768px){.about-text{font-size:1.75rem}}
.about-visual{position:relative;height:400px;border-radius:8px;overflow:hidden;background:linear-gradient(135deg,var(--teal),var(--green))}
.about-visual img{width:100%;height:100%;object-fit:cover;opacity:.7}

/* ===== WHAT WE DO TABS ===== */
.what-we-do{padding:80px 0;background:var(--gray-50)}
.wwd-layout{display:grid;grid-template-columns:1fr;gap:40px}
@media(min-width:768px){.wwd-layout{grid-template-columns:240px 1fr;gap:64px}}
.wwd-tabs{display:flex;flex-direction:row;gap:8px;overflow-x:auto}
@media(min-width:768px){.wwd-tabs{flex-direction:column;gap:0}}
.wwd-tab{padding:14px 20px;font-size:.9375rem;font-weight:500;color:var(--gray-500);cursor:pointer;border:none;background:none;text-align:left;transition:all .2s;white-space:nowrap;position:relative;border-radius:4px}
@media(min-width:768px){.wwd-tab{border-radius:0}}
.wwd-tab:hover{color:var(--gray-700)}
.wwd-tab.active{color:var(--green);font-weight:600;background:var(--white)}
@media(min-width:768px){.wwd-tab.active{border-left:3px solid var(--gold);padding-left:17px;background:var(--white);box-shadow:0 2px 8px rgba(0,0,0,.04)}}
.wwd-panel{display:none;background:var(--white);border-radius:8px;padding:40px;box-shadow:0 2px 12px rgba(0,0,0,.04)}
.wwd-panel.active{display:block}
.wwd-panel-title{font-family:var(--font-serif);font-size:1.75rem;font-weight:600;color:var(--gray-900);margin-bottom:16px}
.wwd-panel-desc{font-size:1rem;color:var(--gray-600);line-height:1.7;margin-bottom:24px}
.wwd-panel-list{list-style:none;margin-bottom:24px}
.wwd-panel-list li{padding:8px 0;color:var(--gray-700);font-size:.9375rem;display:flex;align-items:center;gap:8px}
.wwd-panel-list li::before{content:'';width:6px;height:6px;background:var(--gold);border-radius:50%;flex-shrink:0}

/* ===== NEWSLETTER ===== */
.newsletter{padding:80px 0;background:var(--navy);position:relative;overflow:hidden}
.newsletter::before{content:'';position:absolute;top:-50%;right:-20%;width:600px;height:600px;border-radius:50%;background:var(--green);opacity:.08}
.newsletter-inner{position:relative;z-index:2;max-width:640px;margin:0 auto;text-align:center}
.newsletter-title{font-family:var(--font-serif);font-size:2rem;font-weight:600;color:var(--white);margin-bottom:12px}
.newsletter-desc{font-size:1rem;color:rgba(255,255,255,.7);margin-bottom:32px}
.newsletter-form{display:flex;gap:12px;max-width:480px;margin:0 auto}
.newsletter-form input{flex:1;padding:14px 20px;border-radius:4px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);color:var(--white);font-size:.9375rem;outline:none;transition:border-color .2s}
.newsletter-form input::placeholder{color:rgba(255,255,255,.4)}
.newsletter-form input:focus{border-color:var(--gold)}
.newsletter-form .btn-primary{white-space:nowrap}

/* ===== LATEST INSIGHTS ===== */
.latest-insights{padding:80px 0;background:var(--white)}
.latest-grid{display:grid;grid-template-columns:1fr;gap:32px}
@media(min-width:768px){.latest-grid{grid-template-columns:repeat(3,1fr)}}
.latest-card{border:1px solid var(--gray-200);border-radius:8px;overflow:hidden;transition:box-shadow .3s,transform .3s}
.latest-card:hover{box-shadow:0 8px 32px rgba(0,0,0,.06);transform:translateY(-2px)}
.latest-card-img{height:180px;background:linear-gradient(135deg,var(--teal),var(--green));position:relative}
.latest-card-tag{position:absolute;bottom:12px;left:12px;background:rgba(0,63,45,.85);color:var(--white);padding:4px 10px;border-radius:2px;font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.5px}
.latest-card-body{padding:20px}
.latest-card-meta{font-size:.75rem;color:var(--gray-400);margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px}
.latest-card-title{font-family:var(--font-serif);font-size:1.0625rem;font-weight:600;color:var(--gray-900);line-height:1.4}
.latest-card-title:hover{color:var(--green)}
.latest-card-date{font-size:.8125rem;color:var(--gray-400);margin-top:8px}

/* ===== COMMITMENT ===== */
.commitment{padding:80px 0;background:var(--gray-50)}
.commitment-grid{display:grid;grid-template-columns:1fr;gap:24px}
@media(min-width:768px){.commitment-grid{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1024px){.commitment-grid{grid-template-columns:repeat(4,1fr)}}
.commit-card{background:var(--white);padding:32px;border-radius:8px;border:1px solid var(--gray-200);transition:all .3s}
.commit-card:hover{border-color:var(--green);box-shadow:0 8px 32px rgba(0,63,45,.06)}
.commit-icon{width:48px;height:48px;border-radius:8px;background:rgba(0,63,45,.08);display:flex;align-items:center;justify-content:center;margin-bottom:20px;font-size:1.25rem}
.commit-title{font-family:var(--font-serif);font-size:1.125rem;font-weight:600;color:var(--gray-900);margin-bottom:12px}
.commit-desc{font-size:.875rem;color:var(--gray-500);line-height:1.7;margin-bottom:16px}

/* ===== FOOTER ===== */
.footer{background:var(--navy);padding:64px 0 32px;color:rgba(255,255,255,.7)}
.footer-grid{display:grid;grid-template-columns:1fr;gap:40px;margin-bottom:48px}
@media(min-width:768px){.footer-grid{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1024px){.footer-grid{grid-template-columns:2fr 1fr 1fr 1fr}}
.footer-brand{font-family:var(--font-serif);font-size:1.5rem;font-weight:700;color:var(--white);margin-bottom:16px}
.footer-brand span{color:var(--gold)}
.footer-desc{font-size:.875rem;line-height:1.7;max-width:320px}
.footer-title{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;color:var(--gold);margin-bottom:20px}
.footer-links a{display:block;padding:6px 0;font-size:.875rem;color:rgba(255,255,255,.6);transition:color .2s}
.footer-links a:hover{color:var(--white)}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding-top:24px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;font-size:.8125rem}
.footer-legal{display:flex;gap:24px;flex-wrap:wrap}
.footer-legal a{color:rgba(255,255,255,.5);transition:color .2s}
.footer-legal a:hover{color:var(--white)}
</style>
</head>
<body>

<!-- ===== HEADER ===== -->
<header class="header" id="header">
