    <a href="#" class="btn-primary">Explore the Report</a>
  </div>
</section>

<!-- ===== ABOUT STATEMENT ===== -->
<section class="about">
  <div class="container about-inner">
    <div>
      <div class="section-label">About GlobalStone</div>
      <p class="about-text">We are the global leader in commercial real estate services and investment and a premier provider of critical infrastructure services. With services, insights and data that span every dimension of the industry, we create solutions for clients of every size, in every sector and across every geography.</p>
      <div style="margin-top:24px"><a href="services.html" class="btn-text">Learn More</a></div>
