// Mega Menu
let megaOpen=false;
function toggleMegaMenu(){
  megaOpen=!megaOpen;
  document.getElementById('megaMenu').classList.toggle('open',megaOpen);
  document.getElementById('servicesTrigger').classList.toggle('open',megaOpen);
}
document.addEventListener('click',e=>{
  if(megaOpen && !e.target.closest('#megaMenu') && !e.target.closest('#servicesTrigger')){
    megaOpen=false;
    document.getElementById('megaMenu').classList.remove('open');
    document.getElementById('servicesTrigger').classList.remove('open');
  }
});

// Mobile Nav
let mobileOpen=false;
function toggleMobileNav(){
  mobileOpen=!mobileOpen;
  document.getElementById('hamburger').classList.toggle('open',mobileOpen);
  document.getElementById('mobileNav').classList.toggle('open',mobileOpen);
  document.body.style.overflow=mobileOpen?'hidden':'';
}
function toggleMobileAccordion(el){
  el.classList.toggle('open');
  el.nextElementSibling.classList.toggle('open');
}

// What We Do Tabs
function switchTab(tabId,btn){
  document.querySelectorAll('.wwd-tab').forEach(t=>t.classList.remove('active'));
  document.querySelectorAll('.wwd-panel').forEach(p=>p.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('tab-'+tabId).classList.add('active');
}

// Show nav CTA on desktop
if(window.innerWidth>=1024)document.getElementById('navCta').style.display='inline-flex';

// Newsletter
function handleSubscribe(e){
  e.preventDefault();
  const input=e.target.querySelector('input');
  alert('Thank you for subscribing with '+input.value+'!');
  input.value='';
}
</script>
